<script setup lang="ts">
import { onMounted, ref } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import { workflowApi, type Workflow, type WorkflowExecution, type WorkflowExecutionNode, type WorkflowVersion, type WorkflowTrace } from "@/api/workflows";

const workflows = ref<Workflow[]>([]); const versions = ref<WorkflowVersion[]>([]); const executions = ref<WorkflowExecution[]>([]); const selected = ref<Workflow>(); const selectedVersion = ref<WorkflowVersion>(); const execution = ref<WorkflowExecution>(); const executionNodes = ref<WorkflowExecutionNode[]>([]); const traces = ref<WorkflowTrace[]>([]); const audits = ref<Array<Record<string, unknown>>>([]); const loading = ref(false); const auditLoading = ref(false); const executionListLoading = ref(false); const executionLoading = ref(false); const executionActionLoading = ref(false); const form = ref({ name: "", description: "" }); const editForm = ref({ name: "", description: "" }); const editing = ref(false); const definitionText = ref('{\n  "nodes": [],\n  "edges": []\n}'); const executionInputText = ref("{}"); const executionId = ref(""); const traceExecutionId = ref("");
const statusText: Record<string, string> = { draft: "草稿", published: "已发布", archived: "已归档", pending: "等待中", running: "运行中", completed: "已完成", failed: "失败", cancelled: "已取消", retrying: "重试中", skipped: "已跳过" };
const actionText: Record<string, string> = { create: "创建", update: "更新", publish: "发布", archive: "归档", execute: "执行", cancel: "取消", retry: "重试", resume: "恢复" };
const eventText: Record<string, string> = { execution_started: "执行开始", execution_completed: "执行完成", execution_failed: "执行失败", node_started: "节点开始", node_completed: "节点完成", node_failed: "节点失败", execution_cancelled: "执行取消", execution_retried: "执行重试", execution_resumed: "执行恢复" };
const displayStatus = (value?: string) => value ? statusText[value] || `未知状态（${value}）` : "-";
const displayAction = (value?: string) => value ? actionText[value] || `未知操作（${value}）` : "-";
const displayEvent = (value?: string) => value ? eventText[value] || `未知事件（${value}）` : "-";
const displayErrorMessage = (value?: string) => { if (!value) return "-"; return /^\s*(?:HTTP\s*)?[45]\d\d\b/i.test(value) ? "请求处理失败，请根据错误代码排查" : value; };
const canEditMetadata = (workflow?: Workflow) => Boolean(workflow && workflow.status !== "archived");
const canDelete = (workflow?: Workflow) => workflow?.status === "draft";
const canCreateVersion = (workflow?: Workflow) => Boolean(workflow && workflow.status !== "archived");
const canPublish = (workflow?: Workflow, version?: WorkflowVersion) => Boolean(workflow && version && workflow.status !== "archived" && version.status !== "published" && workflow.published_version_id !== version.id);

async function load() { loading.value = true; try { workflows.value = (await workflowApi.list()).data; if (selected.value) { const fresh = workflows.value.find((item) => item.id === selected.value?.id); if (fresh) selected.value = fresh; } } catch { ElMessage.error("工作流查询失败，请刷新后重试"); } finally { loading.value = false; } }
async function loadExecutions(workflowId: string) { executionListLoading.value = true; try { executions.value = (await workflowApi.listExecutions(workflowId)).data; } catch { ElMessage.error("工作流运行记录查询失败，请稍后重试"); } finally { executionListLoading.value = false; } }
async function selectWorkflow(row: Workflow) { selected.value = row; selectedVersion.value = undefined; execution.value = undefined; executionNodes.value = []; traces.value = []; executionId.value = ""; editing.value = false; editForm.value = { name: row.name, description: row.description }; try { const [versionsResponse] = await Promise.all([workflowApi.versions(row.id), loadExecutions(row.id)]); versions.value = versionsResponse.data; } catch { ElMessage.error("工作流版本查询失败，请稍后重试"); } }
function selectExecution(item: WorkflowExecution) { executionId.value = item.id; void loadExecutionDetails(item.id); }
async function createWorkflow() { if (!form.value.name.trim()) return ElMessage.warning("请输入工作流名称"); try { const created = (await workflowApi.create(form.value)).data; ElMessage.success("工作流创建成功"); form.value = { name: "", description: "" }; await load(); await selectWorkflow(created); } catch { ElMessage.error("工作流创建失败，请稍后重试"); } }
function beginEdit() { if (!selected.value || !canEditMetadata(selected.value)) return; editForm.value = { name: selected.value.name, description: selected.value.description }; editing.value = true; }
function cancelEdit() { if (selected.value) editForm.value = { name: selected.value.name, description: selected.value.description }; editing.value = false; }
async function saveEdit() { if (!selected.value || !canEditMetadata(selected.value)) return; if (!editForm.value.name.trim()) return ElMessage.warning("请输入工作流名称"); try { const updated = (await workflowApi.update(selected.value.id, { name: editForm.value.name.trim(), description: editForm.value.description.trim() })).data; selected.value = updated; editForm.value = { name: updated.name, description: updated.description }; editing.value = false; await load(); ElMessage.success("工作流信息已更新"); } catch { ElMessage.error("工作流更新失败，请稍后重试"); } }
async function deleteWorkflow() { if (!selected.value || !canDelete(selected.value)) return ElMessage.warning("仅草稿工作流允许删除，已发布或已归档工作流不可删除"); try { await ElMessageBox.confirm(`删除工作流「${selected.value.name}」后，其版本、Trigger 和运行记录将不再作为当前工作流使用。此操作不可恢复，是否继续？`, "删除工作流", { type: "warning", confirmButtonText: "确认删除", cancelButtonText: "取消" }); await workflowApi.delete(selected.value.id); ElMessage.success("工作流已删除"); selected.value = undefined; versions.value = []; executions.value = []; execution.value = undefined; await load(); } catch (error) { if (error !== "cancel" && error !== "close") ElMessage.error("工作流删除失败，请稍后重试"); } }
async function saveVersion() { if (!selected.value || !canCreateVersion(selected.value)) return ElMessage.warning("已归档工作流不可创建新版本"); try { const definition = JSON.parse(definitionText.value) as Record<string, unknown>; const version = (await workflowApi.createVersion(selected.value.id, definition)).data; ElMessage.success(`版本 ${version.version} 创建成功`); await selectWorkflow(selected.value); selectedVersion.value = version; } catch (error) { ElMessage.error(error instanceof SyntaxError ? "工作流定义不是合法的 JSON" : "版本创建失败，请稍后重试"); } }
async function publishVersion(version: WorkflowVersion) { if (!selected.value) return; if (!canPublish(selected.value, version)) return ElMessage.warning(selected.value.status === "archived" ? "已归档工作流不可发布版本" : "该版本已经发布或已是当前生效版本"); try { await ElMessageBox.confirm(`确认发布版本 ${version.version}？发布后该版本将成为当前生效版本，并用于后续运行。`, "发布工作流", { type: "warning", confirmButtonText: "确认发布", cancelButtonText: "取消" }); await workflowApi.publish(selected.value.id, version.id); ElMessage.success("工作流版本发布成功"); await load(); await selectWorkflow({ ...selected.value }); } catch (error) { if (error !== "cancel" && error !== "close") ElMessage.error("工作流版本发布失败，请稍后重试"); } }
async function createExecution() { if (!selected.value?.published_version_id) return ElMessage.warning("请先发布一个工作流版本"); try { const inputData = JSON.parse(executionInputText.value) as Record<string, unknown>; executionActionLoading.value = true; const response = await workflowApi.createExecution(selected.value.id, inputData); execution.value = response.data; executionId.value = response.data.id; executionNodes.value = []; await loadExecutions(selected.value.id); ElMessage.success("工作流运行记录创建成功"); } catch (error) { ElMessage.error(error instanceof SyntaxError ? "运行输入不是合法的 JSON" : "创建运行记录失败，请稍后重试"); } finally { executionActionLoading.value = false; } }
async function runExecution() { const id = execution.value?.id || executionId.value.trim(); if (!id) return ElMessage.warning("请先创建或输入工作流运行记录 ID"); executionActionLoading.value = true; try { execution.value = (await workflowApi.runExecution(id)).data; executionId.value = id; executionNodes.value = (await workflowApi.executionNodes(id)).data; if (selected.value) await loadExecutions(selected.value.id); ElMessage.success("工作流已提交运行"); } catch { ElMessage.error("工作流运行失败，请查看运行记录后重试"); } finally { executionActionLoading.value = false; } }
async function cancelExecution() { if (!execution.value || !["pending", "running"].includes(execution.value.status)) return; try { const result = await ElMessageBox.prompt("可选：填写取消原因", "取消工作流运行", { inputPlaceholder: "例如：业务方要求停止", confirmButtonText: "确认取消", cancelButtonText: "返回", inputValidator: (value) => value.length <= 500 || "取消原因不能超过 500 个字符", type: "warning" }); executionActionLoading.value = true; execution.value = (await workflowApi.cancelExecution(execution.value.id, result.value)).data; await loadExecutionDetails(execution.value.id); if (selected.value) await loadExecutions(selected.value.id); ElMessage.success("工作流运行已取消"); } catch (error) { if (error !== "cancel" && error !== "close") ElMessage.error("取消工作流运行失败，请稍后重试"); } finally { executionActionLoading.value = false; } }
async function retryExecution() { if (!execution.value || execution.value.status !== "failed") return; try { await ElMessageBox.confirm("将使用原失败运行记录的输入和版本创建新的运行记录，是否继续？", "重试工作流运行", { type: "warning" }); executionActionLoading.value = true; execution.value = (await workflowApi.retryExecution(execution.value.id)).data; executionId.value = execution.value.id; executionNodes.value = []; if (selected.value) await loadExecutions(selected.value.id); ElMessage.success("新的重试运行记录已创建，可继续运行"); } catch (error) { if (error !== "cancel" && error !== "close") ElMessage.error("创建重试运行记录失败，请稍后重试"); } finally { executionActionLoading.value = false; } }
async function resumeExecution() { if (!execution.value?.resume_checkpoint_sequence || ["pending", "running"].includes(execution.value.status)) return; try { await ElMessageBox.confirm(`将从检查点 #${execution.value.resume_checkpoint_sequence} 创建新的持久化恢复运行记录，是否继续？`, "恢复工作流运行", { type: "warning" }); executionActionLoading.value = true; execution.value = (await workflowApi.resumeExecution(execution.value.id)).data; executionId.value = execution.value.id; executionNodes.value = []; if (selected.value) await loadExecutions(selected.value.id); ElMessage.success("新的恢复运行记录已创建"); } catch (error) { if (error !== "cancel" && error !== "close") ElMessage.error("创建恢复运行记录失败，请稍后重试"); } finally { executionActionLoading.value = false; } }
async function loadExecutionDetails(id: string) { const [executionResponse, nodesResponse] = await Promise.all([workflowApi.execution(id), workflowApi.executionNodes(id)]); execution.value = executionResponse.data; executionNodes.value = nodesResponse.data; executionId.value = id; }
async function loadExecution() { const id = executionId.value.trim(); if (!id) return ElMessage.warning("请输入工作流运行记录 ID"); executionLoading.value = true; try { await loadExecutionDetails(id); } catch { ElMessage.error("工作流运行记录查询失败，请检查 ID 后重试"); } finally { executionLoading.value = false; } }
async function loadAudit() { if (!selected.value) return; auditLoading.value = true; try { audits.value = (await workflowApi.audit({ page: 1, page_size: 50, workflow_id: selected.value.id })).data.items; } catch { ElMessage.error("审计记录查询失败，请稍后重试"); } finally { auditLoading.value = false; } }
async function loadTrace() { if (!traceExecutionId.value.trim()) return ElMessage.warning("请输入工作流运行记录 ID"); try { traces.value = (await workflowApi.trace(traceExecutionId.value.trim())).data.items; } catch { ElMessage.error("运行链路查询失败，请检查 ID 后重试"); } }
function useVersion(version: WorkflowVersion) { selectedVersion.value = version; definitionText.value = JSON.stringify(version.definition, null, 2); }
onMounted(load);
</script>
<template>
<div class="workflow-page"><el-row :gutter="16"><el-col :span="8"><el-card v-loading="loading"><template #header><div class="header"><span>工作流管理</span><el-button type="primary" size="small" @click="load">刷新</el-button></div></template><el-form label-position="top" @submit.prevent="createWorkflow"><el-form-item label="名称"><el-input v-model="form.name" placeholder="请输入企业流程名称" /></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea" :rows="2" placeholder="请输入工作流用途说明" /></el-form-item><el-button type="primary" native-type="submit">创建工作流</el-button></el-form><el-divider /><el-table :data="workflows" highlight-current-row @row-click="selectWorkflow"><el-table-column prop="name" label="工作流" min-width="150" /><el-table-column prop="status" label="状态" width="90"><template #default="scope">{{ displayStatus(scope.row.status) }}</template></el-table-column><el-table-column prop="updated_at" label="更新时间" min-width="170" /></el-table><el-empty v-if="!workflows.length && !loading" description="暂无工作流" /></el-card></el-col>
<el-col :span="16"><el-card v-if="selected"><template #header><div class="header"><span>{{ selected.name }} / 治理信息</span><div class="header-actions"><el-tag>{{ displayStatus(selected.status) }}</el-tag><el-button v-if="canEditMetadata(selected)" size="small" @click="beginEdit">编辑</el-button><el-button v-if="canDelete(selected)" size="small" type="danger" @click="deleteWorkflow">删除</el-button></div></div></template>
<el-form v-if="editing" label-position="top" class="edit-form"><el-form-item label="工作流名称"><el-input v-model="editForm.name" /></el-form-item><el-form-item label="描述"><el-input v-model="editForm.description" type="textarea" :rows="2" /></el-form-item><div class="trace-query"><el-button type="primary" @click="saveEdit">保存</el-button><el-button @click="cancelEdit">取消</el-button></div></el-form>
<el-descriptions v-else :column="2" border><el-descriptions-item label="工作流 ID">{{ selected.id }}</el-descriptions-item><el-descriptions-item label="已发布版本 ID">{{ selected.published_version_id || '-' }}</el-descriptions-item><el-descriptions-item label="负责人 ID">{{ selected.owner_id }}</el-descriptions-item><el-descriptions-item label="更新时间">{{ selected.updated_at }}</el-descriptions-item></el-descriptions><el-alert v-if="selected.status === 'published'" title="当前工作流已有生效版本；修改流程定义请创建新版本，发布后才会切换当前生效版本。" type="info" :closable="false" class="lifecycle-alert" /><el-alert v-if="selected.status === 'archived'" title="已归档工作流为只读状态，不允许编辑、创建版本、发布或删除。" type="warning" :closable="false" class="lifecycle-alert" /><el-tabs @tab-change="(name) => name === 'audit' && loadAudit()">
<el-tab-pane label="版本" name="versions"><el-table :data="versions" @row-click="useVersion"><el-table-column prop="version" label="版本" width="90" /><el-table-column prop="status" label="状态" width="110"><template #default="scope">{{ displayStatus(scope.row.status) }}</template></el-table-column><el-table-column prop="created_at" label="创建时间" min-width="180" /><el-table-column label="操作" width="110"><template #default="scope"><el-button size="small" type="success" :disabled="!canPublish(selected, scope.row as WorkflowVersion)" @click.stop="publishVersion(scope.row as WorkflowVersion)">发布</el-button></template></el-table-column></el-table><el-empty v-if="!versions.length" description="暂无版本" /></el-tab-pane>
<el-tab-pane label="定义" name="definition"><el-alert title="当前使用 JSON 工作流定义；后续可升级为可视化流程编排器。已发布工作流通过创建新版本进行修改，不直接覆盖当前生效版本。" type="info" :closable="false" /><el-input v-model="definitionText" type="textarea" :rows="18" class="definition" :disabled="!canCreateVersion(selected)" /><el-button type="primary" :disabled="!canCreateVersion(selected)" @click="saveVersion">创建新版本</el-button></el-tab-pane>
<el-tab-pane label="运行" name="execution"><el-alert title="运行记录来自后端持久化数据，可查看历史运行、重试，并从已有检查点恢复运行。" type="info" :closable="false" /><el-table v-loading="executionListLoading" :data="executions" highlight-current-row @row-click="selectExecution"><el-table-column prop="id" label="运行记录 ID" min-width="180" /><el-table-column prop="status" label="状态" width="110"><template #default="scope">{{ displayStatus(scope.row.status) }}</template></el-table-column><el-table-column prop="workflow_version_id" label="版本 ID" min-width="150" /><el-table-column prop="created_at" label="创建时间" min-width="170" /></el-table><el-empty v-if="!executions.length && !executionListLoading" description="暂无运行记录" /><el-input v-model="executionInputText" type="textarea" :rows="5" class="execution-input" placeholder='请输入 JSON，例如：{"key":"value"}' /><div class="trace-query"><el-button type="primary" :loading="executionActionLoading" :disabled="!selected.published_version_id" @click="createExecution">创建运行记录</el-button><el-button type="success" :loading="executionActionLoading" :disabled="!execution || execution.status !== 'pending'" @click="runExecution">运行</el-button><el-button type="warning" :loading="executionActionLoading" :disabled="!execution || !['pending', 'running'].includes(execution.status)" @click="cancelExecution">取消运行</el-button><el-button type="danger" :loading="executionActionLoading" :disabled="!execution || execution.status !== 'failed'" @click="retryExecution">重试</el-button><el-button type="warning" plain :loading="executionActionLoading" :disabled="!execution || !execution.resume_checkpoint_sequence || ['pending', 'running'].includes(execution.status)" @click="resumeExecution">恢复运行</el-button></div><div class="trace-query"><el-input v-model="executionId" placeholder="请输入运行记录 ID" @keyup.enter="loadExecution" /><el-button type="primary" :loading="executionLoading" @click="loadExecution">查询运行记录</el-button></div><template v-if="execution"><el-descriptions :column="2" border class="execution-summary"><el-descriptions-item label="运行记录 ID">{{ execution.id }}</el-descriptions-item><el-descriptions-item label="状态"><el-tag>{{ displayStatus(execution.status) }}</el-tag></el-descriptions-item><el-descriptions-item label="工作流版本 ID">{{ execution.workflow_version_id }}</el-descriptions-item><el-descriptions-item label="重试来源 ID">{{ execution.retry_of_execution_id || '-' }}</el-descriptions-item><el-descriptions-item label="恢复来源 ID">{{ execution.resume_of_execution_id || '-' }}</el-descriptions-item><el-descriptions-item label="恢复检查点">{{ execution.resume_checkpoint_sequence ?? '-' }}</el-descriptions-item><el-descriptions-item label="当前节点">{{ execution.current_node_id || '-' }}</el-descriptions-item><el-descriptions-item label="开始时间">{{ execution.started_at || '-' }}</el-descriptions-item><el-descriptions-item label="结束时间">{{ execution.ended_at || '-' }}</el-descriptions-item><el-descriptions-item v-if="execution.error_code" label="错误代码">{{ execution.error_code }}<span v-if="execution.error_message">：{{ displayErrorMessage(execution.error_message) }}</span></el-descriptions-item></el-descriptions><el-table :data="executionNodes" class="execution-nodes"><el-table-column prop="node_id" label="节点 ID" min-width="140" /><el-table-column prop="status" label="状态" width="110"><template #default="scope">{{ displayStatus(scope.row.status) }}</template></el-table-column><el-table-column prop="attempt" label="尝试次数" width="90" /><el-table-column prop="started_at" label="开始时间" min-width="170" /><el-table-column prop="error_code" label="错误代码" width="140" /></el-table></template><el-empty v-else description="请选择或查询运行记录" /></el-tab-pane>
<el-tab-pane label="审计" name="audit"><el-table v-loading="auditLoading" :data="audits"><el-table-column prop="action" label="操作"><template #default="scope">{{ displayAction(scope.row.action as string) }}</template></el-table-column><el-table-column prop="status" label="状态"><template #default="scope">{{ displayStatus(scope.row.status as string) }}</template></el-table-column><el-table-column prop="created_at" label="创建时间" min-width="180" /><el-table-column prop="error_code" label="错误代码" width="130" /></el-table><el-empty v-if="!audits.length && !auditLoading" description="暂无审计记录" /></el-tab-pane>
<el-tab-pane label="运行链路" name="trace"><el-alert title="输入运行记录 ID，查看完整的运行链路。" type="info" :closable="false" /><div class="trace-query"><el-input v-model="traceExecutionId" placeholder="请输入运行记录 ID" @keyup.enter="loadTrace" /><el-button type="primary" @click="loadTrace">查询运行链路</el-button></div><el-timeline v-if="traces.length" class="trace-list"><el-timeline-item v-for="item in traces" :key="item.id" :timestamp="item.created_at"><strong>{{ displayEvent(item.event_type) }}</strong> / {{ displayStatus(item.status) }} / 节点：{{ item.node_id || '-' }}<div v-if="item.error_code" class="error">{{ item.error_code }}<span v-if="item.error_message">：{{ displayErrorMessage(item.error_message) }}</span></div></el-timeline-item></el-timeline><el-empty v-else description="暂无运行链路" /></el-tab-pane></el-tabs></el-card><el-empty v-else description="请选择工作流" /></el-col></el-row></div>
</template>
<style scoped>.workflow-page { padding: 16px; }.header { display: flex; align-items: center; justify-content: space-between; }.header-actions { display: flex; align-items: center; gap: 8px; }.edit-form { margin-top: 16px; }.lifecycle-alert { margin-top: 12px; }.definition { margin: 12px 0; font-family: monospace; }.execution-input { margin-top: 12px; font-family: monospace; }.trace-query { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }.trace-query .el-input { flex: 1; min-width: 220px; }.execution-summary { margin-top: 16px; }.execution-nodes { margin-top: 16px; }.trace-list { margin-top: 20px; }.error { margin-top: 4px; }</style>
